RED.plugins = (function() {
    var plugins = {};
    var pluginsByType = {};
    var moduleList = {};

    function registerPlugin(id,definition) {
        plugins[id] = definition;
        if (definition.type) {
            pluginsByType[definition.type] = pluginsByType[definition.type] || [];
            pluginsByType[definition.type].push(definition);
        }
        if (RED._loadingModule) {
            definition.module = RED._loadingModule;
            definition["_"] = function() {
                var args = Array.prototype.slice.call(arguments);
                var originalKey = args[0];
                if (!/:/.test(args[0])) {
                    args[0] = definition.module+":"+args[0];
                }
                var result = RED._.apply(null,args);
                if (result === args[0]) {
                    return originalKey;
                }
                return result;
            }
        } else {
            definition["_"] = RED["_"]
        }
        if (definition.onadd && typeof definition.onadd === 'function') {
            definition.onadd();
        }
        RED.events.emit("registry:plugin-added",id);
    }

    function getPlugin(id) {
        return plugins[id]
    }

    function getPluginsByType(type) {
        return pluginsByType[type] || [];
    }

    function setPluginList(list) {
        for(let i=0;i<list.length;i++) {
            let p = list[i];
            addPlugin(p);
        }
    }

    function addPlugin(p) {

        moduleList[p.module] = moduleList[p.module] || {
            name:p.module,
            version:p.version,
            local:p.local,
            sets:{},
            plugin: true,
            id: p.id
        };
        if (p.pending_version) {
            moduleList[p.module].pending_version = p.pending_version;
        }
        moduleList[p.module].sets[p.name] = p;

        RED.events.emit("registry:plugin-module-added",p.module);
    }

    function getModule(module) {
        return moduleList[module];
    }

    function removePlugin(id) {
        var p = plugins[id];
        var module = p ? p.module : null;
        delete plugins[id];
        if (p && p.type && pluginsByType[p.type]) {
            var i = pluginsByType[p.type].indexOf(p);
            if (i > -1) {
                pluginsByType[p.type].splice(i,1);
            }
        }
        if (p && p.module && moduleList[p.module]) {
            delete moduleList[p.module].sets[p.name];
            if (Object.keys(moduleList[p.module].sets).length === 0) {
                delete moduleList[p.module];
            }
        }
        // Pass the module along with the id - the plugin is already removed
        // by the time listeners run, so the module can't be looked up from id.
        RED.events.emit("registry:plugin-removed",{id:id,module:module});
        return p;
    }

    function removeModule(module) {
        var m = moduleList[module];
        if (m) {
            Object.keys(m.sets).forEach(function(setName) {
                var set = m.sets[setName];
                (set.plugins||[]).forEach(function(p) {
                    removePlugin(p.id);
                });
            });
        }
    }

    return {
        registerPlugin: registerPlugin,
        getPlugin: getPlugin,
        getPluginsByType: getPluginsByType,

        setPluginList: setPluginList,
        addPlugin: addPlugin,
        getModule: getModule,
        removePlugin: removePlugin,
        removeModule: removeModule
    }
})();
